mapper.select:
SELECT r.* FROM afv_media_resource r JOIN afv_media_source s ON s.resource_id = r.id
WHERE s.source_type = #{type} AND s.source_id = #{id} AND s.source_version = #{version} AND s.source_field = #{field}
FOR UPDATE

SELECT 'BUSINESS_SOURCE' AS anchor_kind FROM afv_media_source WHERE resource_id=#{mediaId}
UNION ALL SELECT 'BUSINESS_BINDING' FROM afv_media_binding WHERE media_id=#{mediaId}
UNION ALL SELECT 'PRESET' FROM afv_media_preset_binding WHERE media_id=#{mediaId}
UNION ALL SELECT 'PREVIEW_SOURCE' FROM afv_media_preview_job WHERE source_resource_id=#{mediaId}
UNION ALL SELECT 'PREVIEW_OUTPUT' FROM afv_media_preview_job WHERE output_resource_id=#{mediaId}
UNION ALL SELECT 'ACCESS_TICKET' FROM afv_media_access_ticket
    WHERE resource_id=#{mediaId} AND revoked=FALSE AND expires_at>UTC_TIMESTAMP(6)
UNION ALL SELECT 'GENERATION_INPUT' FROM afv_remote_generation_job j
    JOIN afv_generation_submission s ON s.id=j.submission_id
    WHERE JSON_CONTAINS_PATH(j.input_json,'one',CONCAT('$.inputMediaVersions."',#{mediaId},'"'))
UNION ALL SELECT 'MEDIA_JOB_OUTPUT' FROM afv_media_resource m JOIN afv_media_job j
    ON m.created_by=j.actor_user_id AND m.request_id LIKE CONCAT('job:',j.id,':%')
    WHERE m.id=#{mediaId}
UNION ALL SELECT 'GENERATION_OUTPUT' FROM afv_media_resource m JOIN afv_generation_submission s
    ON m.created_by=s.actor_user_id
       AND m.request_id LIKE CONCAT('generation:',LOWER(s.kind),':',s.task_id,':%')
    WHERE m.id=#{mediaId}
LIMIT 1

SELECT r.* FROM afv_media_resource r WHERE state = 'READY' AND

    project_id IS NULL AND owner_type = #{ownerType} AND owner_id = #{ownerId}
    project_id = #{projectId}

AND NOT EXISTS (SELECT 1 FROM afv_media_preview_job p WHERE p.output_resource_id = r.id)
ORDER BY created_at DESC, id DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE afv_media_resource SET blob_id = #{blobId}, ingest_epoch = #{epoch}, state = 'STAGING',
    version = version + 1, last_error = NULL, lease_until = TIMESTAMPADD(MINUTE, 10, UTC_TIMESTAMP(6)),
    updated_at = UTC_TIMESTAMP(6) WHERE id = #{id}
